 private JsonNode user(String username,String phone,String first,String last)throws Exception{MvcResult r=mvc.perform(post("/api/users").contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(new UserPayload(username,phone,"secret123",first,last,"Test")))).andExpect(status().isOk()).andReturn();return json.readTree(r.getResponse().getContentAsString());}
 private String login(JsonNode user)throws Exception{MvcResult r=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"identifier\":\""+user.get("phoneNumber").asText()+"\",\"password\":\"secret123\"}")).andExpect(status().isOk()).andReturn();return json.readTree(r.getResponse().getContentAsString()).get("accessToken").asText();} private String bearer(String t){return "Bearer "+t;} private record UserPayload(String username,String phoneNumber,String password,String firstName,String surname,String location){}
